import { useState, useEffect, useRef, useMemo } from 'react';
import { useTheme } from '../../Common/ThemeContext';
import styles from './NavbarStyles.module.css';

function Navbar() {
  const [activeSection, setActiveSection] = useState('home');
  const [isScrolling, setIsScrolling] = useState(false);
  const scrollTimeout = useRef(null);
  const { theme } = useTheme();
  const sections = useMemo(() => ['home', 'skills', 'projects', 'contact'], []);

  useEffect(() => {
    const handleHashChange = () => {
      const hash = window.location.hash.replace('#', '');
      if (hash === 'subu' || hash === '') {
        setActiveSection('home');
      } else if (sections.includes(hash)) {
        setActiveSection(hash);
      }
      setIsScrolling(true);
      resetInactivityTimer();
    };

    const sectionObserver = new IntersectionObserver(
      (entries) => {
        entries.forEach(entry => {
          if (entry.isIntersecting) {
            const sectionId = entry.target.id === 'subu' ? 'home' : entry.target.id;
            setActiveSection(sectionId);
            setIsScrolling(true);
            resetInactivityTimer();
          }
        });
      },
      {
        threshold: 0.5,
        rootMargin: '0px 0px -50% 0px'
      }
    );

    const handleScroll = () => {
      setIsScrolling(true);
      resetInactivityTimer();
      clearTimeout(scrollTimeout.current);
    };

    const resetInactivityTimer = () => {
      clearTimeout(scrollTimeout.current);
      scrollTimeout.current = setTimeout(() => {
        setIsScrolling(false);
      }, 10000); // 10 seconds
    };

    // Initial check for hash
    handleHashChange();

    sections.forEach(section => {
      const element = document.getElementById(section === 'home' ? 'subu' : section);
      if (element) sectionObserver.observe(element);
    });

    window.addEventListener('scroll', handleScroll);
    window.addEventListener('hashchange', handleHashChange);
    resetInactivityTimer();

    return () => {
      sections.forEach(section => {
        const element = document.getElementById(section === 'home' ? 'subu' : section);
        if (element) sectionObserver.unobserve(element);
      });
      sectionObserver.disconnect();
      window.removeEventListener('scroll', handleScroll);
      window.removeEventListener('hashchange', handleHashChange);
      clearTimeout(scrollTimeout.current);
    };
  }, [sections]);

  return (
    <nav aria-label="Main navigation" className={`${styles.navbar} ${theme === 'dark' ? styles.dark : styles.light}`}>
      <ul>
        {sections.map((section) => (
          <li 
            key={section}
            className={`${activeSection === section ? styles.active : ''} ${isScrolling ? styles.visible : ''}`}
          >
            <a href={`#${section === 'home' ? 'subu' : section}`}>
              {section.charAt(0).toUpperCase() + section.slice(1)}
            </a>
          </li>
        ))}
      </ul>
    </nav>
  );
}

export default Navbar;
